<template>
  <F7Page class="!bg-stock-bg [&_.page-content]:!bg-stock-bg">
    <F7Navbar title="Profile" large transparent :sliding="true">
      <template #nav-right>
        <div class="flex items-center gap-2 pr-3">
          <F7Link icon-only class="!h-10 !w-10" @click="openSyncErrors">
            <span
              class="glass-surface relative flex h-10 w-10 min-w-[40px] shrink-0 items-center justify-center rounded-[13px]"
            >
              <ILucideTriangleAlert class="h-[18px] w-[18px] text-ink-soft" />
            </span>
          </F7Link>

          <F7Link icon-only class="!h-10 !w-10" @click="handleUpdateItemClick">
            <span
              class="glass-surface relative flex h-10 w-10 min-w-[40px] shrink-0 items-center justify-center rounded-[13px]"
            >
              <F7Preloader v-if="isChecking || isDownloading" size="18" />
              <ILucideRefreshCw v-else class="h-[18px] w-[18px] text-ink-soft" />
              <span
                v-if="updateAvailable"
                class="absolute -right-1 -top-1 flex h-[18px] min-w-[18px] items-center justify-center rounded-full bg-[#ff3b30] px-1 text-[10px] font-[760] text-white ring-2 ring-white"
              >
                1
              </span>
            </span>
          </F7Link>
        </div>
      </template>
    </F7Navbar>

    <div class="px-4 pt-2">
      <MoreProfileCard />
    </div>

    <F7BlockTitle>Preferences</F7BlockTitle>
    <F7List inset strong dividers-ios>
      <F7ListItem
        popup-open="#theme-popup"
        link
        title="Theme"
        :after="themeModeLabel"
      >
        <template #media>
          <span :class="tile" class="bg-[#6366f1]"
            ><ILucidePalette class="h-[17px] w-[17px]"
          /></span>
        </template>
      </F7ListItem>

      <F7ListItem title="Notifications">
        <template #media>
          <span :class="tile" class="bg-[#ff3b30]"
            ><ILucideBell class="h-[17px] w-[17px]"
          /></span>
        </template>
        <template #after>
          <F7Toggle
            :checked="settingsStore.notificationsEnabled"
            @change="settingsStore.toggleNotifications"
          />
        </template>
      </F7ListItem>

      <F7ListItem link title="Language" after="English" @click="comingSoon">
        <template #media>
          <span :class="tile" class="bg-[#14b8a6]"
            ><ILucideLanguages class="h-[17px] w-[17px]"
          /></span>
        </template>
      </F7ListItem>
    </F7List>

    <F7BlockTitle>General</F7BlockTitle>
    <F7List inset strong dividers-ios>
      <F7ListItem
        link
        title="About"
        footer="App information"
        @click="comingSoon"
      >
        <template #media>
          <span :class="tile" class="bg-[#1f6df5]"
            ><ILucideInfo class="h-[17px] w-[17px]"
          /></span>
        </template>
      </F7ListItem>

      <F7ListItem title="Version" :after="`v${appVersion}`">
        <template #media>
          <span :class="tile" class="bg-[#8e8e93]"
            ><ILucideTag class="h-[17px] w-[17px]"
          /></span>
        </template>
      </F7ListItem>

      <F7ListItem title="In zone" footer="Restrict activity to assigned zone">
        <template #media>
          <span :class="tile" class="bg-[#34c759]"
            ><ILucideMapPin class="h-[17px] w-[17px]"
          /></span>
        </template>
        <template #after>
          <F7Toggle
            :checked="inZoneEnabled"
            @change="inZoneEnabled = !inZoneEnabled"
          />
        </template>
      </F7ListItem>

      <F7ListItem title="AI scan" footer="Image recognition assist">
        <template #media>
          <span :class="tile" class="bg-[#8b2af3]"
            ><ILucideSparkles class="h-[17px] w-[17px]"
          /></span>
        </template>
        <template #after>
          <F7Toggle
            :checked="aiScanEnabled"
            @change="aiScanEnabled = !aiScanEnabled"
          />
        </template>
      </F7ListItem>
    </F7List>

    <F7BlockTitle>Sync</F7BlockTitle>
    <F7List inset strong dividers-ios>
      <F7ListItem
        link
        title="Sync interval"
        after="Every 30 min"
        @click="comingSoon"
      >
        <template #media>
          <span :class="tile" class="bg-[#1f6df5]"
            ><ILucideTimer class="h-[17px] w-[17px]"
          /></span>
        </template>
      </F7ListItem>

      <F7ListItem
        link
        title="Force sync now"
        footer="Push pending changes"
        @click="comingSoon"
      >
        <template #media>
          <span :class="tile" class="bg-[#00b8d4]"
            ><ILucideCloudUpload class="h-[17px] w-[17px]"
          /></span>
        </template>
      </F7ListItem>

      <F7ListItem link title="Clear & resync database" @click="handleClearSync">
        <template #media>
          <span :class="tile" class="bg-[#ff9500]"
            ><ILucideDatabaseBackup class="h-[17px] w-[17px]"
          /></span>
        </template>
      </F7ListItem>

      <F7ListItem link="/settings/sync-errors" title="Sync errors">
        <template #media>
          <span :class="tile" class="bg-[#ff3b30]"
            ><ILucideTriangleAlert class="h-[17px] w-[17px]"
          /></span>
        </template>
      </F7ListItem>
    </F7List>

    <F7BlockTitle>Database</F7BlockTitle>
    <F7List inset strong dividers-ios>
      <F7ListItem link title="Export database" @click="comingSoon">
        <template #media>
          <span :class="tile" class="bg-[#34c759]"
            ><ILucideDownload class="h-[17px] w-[17px]"
          /></span>
        </template>
      </F7ListItem>

      <F7ListItem link title="Share database" @click="comingSoon">
        <template #media>
          <span :class="tile" class="bg-[#1f6df5]"
            ><ILucideShare2 class="h-[17px] w-[17px]"
          /></span>
        </template>
      </F7ListItem>

      <F7ListItem link @click="comingSoon">
        <template #title>
          <span class="font-[600] text-[#ff3b30]">Delete database</span>
        </template>
        <template #media>
          <span :class="tile" class="bg-[#ff3b30]"
            ><ILucideTrash2 class="h-[17px] w-[17px]"
          /></span>
        </template>
      </F7ListItem>
    </F7List>

    <F7BlockTitle>Printing</F7BlockTitle>
    <F7List inset strong dividers-ios>
      <F7ListItem
        link
        title="Print driver"
        footer="No printer connected"
        @click="comingSoon"
      >
        <template #media>
          <span :class="tile" class="bg-[#475569]"
            ><ILucidePrinter class="h-[17px] w-[17px]"
          /></span>
        </template>
      </F7ListItem>

      <F7ListItem link title="Paper & image config" @click="comingSoon">
        <template #media>
          <span :class="tile" class="bg-[#8e8e93]"
            ><ILucideFileText class="h-[17px] w-[17px]"
          /></span>
        </template>
      </F7ListItem>
    </F7List>

    <F7BlockTitle>Updates</F7BlockTitle>
    <F7List inset strong dividers-ios>
      <F7ListItem
        link
        :title="updateAvailable ? 'Update available' : 'Check for updates'"
        :footer="updateStatus"
        @click="handleUpdateItemClick"
      >
        <template #media>
          <span :class="tile" class="bg-[#1f6df5]">
            <ILucideRefreshCw class="h-[17px] w-[17px]" />
          </span>
        </template>
        <template #after>
          <F7Preloader v-if="isChecking || isDownloading" size="20" />
          <F7Badge v-else-if="updateAvailable" color="red">1</F7Badge>
        </template>
      </F7ListItem>
    </F7List>

    <F7BlockTitle>Developer</F7BlockTitle>
    <F7List inset strong dividers-ios>
      <F7ListItem link title="View logs" @click="comingSoon">
        <template #media>
          <span :class="tile" class="bg-[#8e8e93]"
            ><ILucideScrollText class="h-[17px] w-[17px]"
          /></span>
        </template>
        <template #after>
          <F7Badge color="orange">Dev</F7Badge>
        </template>
      </F7ListItem>

      <F7ListItem
        link
        title="Test notification"
        @click="handleTestNotification"
      >
        <template #media>
          <span :class="tile" class="bg-[#ff2d55]"
            ><ILucideBellRing class="h-[17px] w-[17px]"
          /></span>
        </template>
      </F7ListItem>
    </F7List>

    <F7List inset strong class="!mt-6">
      <F7Button large fill color="red" @click="handleLogout">Sign Out</F7Button>
    </F7List>

    <F7Block class="text-center">
      <p class="text-[13px] text-ink-muted">
        Version {{ appVersion }}
        <span v-if="bundleVersion && bundleVersion !== 'builtin'"
          >({{ bundleVersion }})</span
        >
      </p>
      <p class="text-[13px] text-ink-muted">
        {{ appEnvironment }} • {{ appChannel }}
      </p>
      <p class="text-[13px] text-ink-muted">© 2025 Presalio</p>
    </F7Block>

    <AppTheme />
  </F7Page>
</template>

<script setup lang="ts">
import MoreProfileCard from "../components/MoreProfileCard.vue";
import AppTheme from "@/shared/components/app/AppTheme.vue";
import { useUpdater } from "@/shared/services/updater/useUpdater";
import { useNotifications } from "@/shared/composables/useNotifications";
import { useAuth } from "@/modules/auth/composables/useAuth";
import { App } from "@capacitor/app";
import { Capacitor } from "@capacitor/core";

const settingsStore = useSettingsStore();
const appTheme = useAppTheme();
const { logout } = useAuth();
const { notify } = useNotifications();

const {
  check,
  isChecking,
  updateAvailable,
  currentUpdate,
  startDownload,
  isDownloading,
  progress,
} = useUpdater();

const tile =
  "flex h-7 w-7 shrink-0 items-center justify-center rounded-[9px] text-white shadow-[0_2px_5px_rgba(31,58,107,0.18)]";

const appVersion = ref("1.0.0");
const bundleVersion = ref("");
const appEnvironment = ref(import.meta.env.VITE_ENVIRONMENT || "dev");
const appChannel = ref(import.meta.env.VITE_UPDATE_CHANNEL || "prod");

const inZoneEnabled = ref(false);
const aiScanEnabled = ref(false);

const themeModeLabel = computed(() =>
  appTheme.value.darkMode === "dark" ? "Dark" : "Light",
);

const updateStatus = computed(() => {
  if (isChecking.value) return "Checking...";
  if (isDownloading.value) return `Downloading... ${progress.value.percent}%`;
  if (updateAvailable.value && currentUpdate.value)
    return `v${currentUpdate.value.version} available`;
  return "Tap to check for updates";
});

function openSyncErrors() {
  f7.views.current.router.navigate("/settings/sync-errors");
}

function comingSoon() {
  f7.toast
    .create({ text: "Coming soon", position: "center", closeTimeout: 1500 })
    .open();
}

async function loadAppVersion() {
  try {
    if (Capacitor.isNativePlatform()) {
      const info = await App.getInfo();
      appVersion.value = info.version;
      const { CapacitorUpdater } = await import("@capgo/capacitor-updater");
      const current = await CapacitorUpdater.current();
      bundleVersion.value = current.bundle.version;
    } else {
      // @ts-ignore
      appVersion.value = __APP_VERSION__;
    }
  } catch (error) {
    console.error("Error getting app version:", error);
  }
}

async function handleUpdateItemClick() {
  if (isDownloading.value || isChecking.value) return;

  if (updateAvailable.value && currentUpdate.value) {
    f7.dialog.confirm(
      `A new version (${currentUpdate.value.version}) is available. Download and install it now?`,
      "Update Available",
      async () => {
        try {
          await startDownload();
        } catch (error) {
          f7.dialog.alert(`Download failed: ${(error as Error).message}`);
        }
      },
    );
    return;
  }

  try {
    await check(false);
    if (!updateAvailable.value) {
      f7.toast
        .create({
          text: "You're on the latest version!",
          position: "center",
          closeTimeout: 2000,
        })
        .open();
    }
  } catch (error) {
    console.error("Error checking for updates:", error);
    f7.toast
      .create({
        text: "Failed to check for updates",
        position: "center",
        closeTimeout: 2000,
      })
      .open();
  }
}

async function handleClearSync() {
  f7.dialog.confirm(
    "This will clear your local database and resync. Continue?",
    async () => {
      f7.preloader.show();
      try {
        await new Promise((resolve) => setTimeout(resolve, 1000));
        f7.toast
          .create({
            text: "✓ Database cleared and resynced!",
            position: "center",
            closeTimeout: 2000,
          })
          .open();
      } catch (error) {
        f7.dialog.alert("Error resyncing database");
      } finally {
        f7.preloader.hide();
      }
    },
  );
}

function handleTestNotification() {
  f7.dialog
    .create({
      title: "Test Notifications",
      text: "Choose notification type:",
      buttons: [
        {
          text: "In-App (Toast)",
          onClick: () => {
            notify({
              title: "Test In-App",
              body: "This is a Framework7 toast notification!",
              type: "success",
            });
          },
        },
        {
          text: "System (5s Delay)",
          onClick: () => {
            const scheduleDate = new Date(Date.now() + 5000);
            notify({
              title: "Test System",
              body: "This is a scheduled system notification!",
              schedule: scheduleDate,
            });
            f7.toast
              .create({
                text: "Scheduled in 5s. Close the app to test!",
                closeTimeout: 2000,
              })
              .open();
          },
        },
        { text: "Cancel", color: "red" },
      ],
      verticalButtons: true,
    })
    .open();
}

async function handleLogout() {
  f7.dialog.confirm(
    "Are you sure you want to sign out?",
    "Sign Out",
    async () => {
      try {
        await logout();
      } catch (e: any) {
        f7.dialog.alert(e.message || "Logout failed", "Error");
      }
    },
  );
}

onMounted(() => {
  loadAppVersion();
});
</script>
